INSERT INTO mt_promotion_setting_history (
    setting_id, shop_id, version_no, promotion_enabled, strategy_configured, strategy_config_json,
    strategy_config_hash, change_source, operator_user_id, operator_name, change_reason, create_time, update_time
) VALUES (
    #{settingId}, #{shopId}, #{versionNo}, #{promotionEnabled}, #{strategyConfigured}, #{strategyConfigJson},
    #{strategyConfigHash}, #{changeSource}, #{operatorUserId}, #{operatorName}, #{changeReason},
    #{createTime}, #{updateTime}
)

mapper.select:
SELECT MAX(version_no)
FROM mt_promotion_setting_history
WHERE shop_id = #{shopId}

SELECT 
FROM mt_promotion_setting_history
WHERE shop_id = #{shopId}
ORDER BY version_no DESC, id DESC
LIMIT #{limit}

SELECT 
FROM mt_promotion_setting_history
WHERE shop_id = #{shopId}
  AND create_time < #{createTime}
ORDER BY create_time DESC, version_no DESC, id DESC
LIMIT 1

SELECT 
FROM mt_promotion_setting_history
WHERE shop_id = #{shopId}
  AND create_time >= #{startCreateTime}
  AND create_time < #{endCreateTime}
ORDER BY create_time ASC, version_no ASC, id ASC
